  if (verifyEmails) {
    await queueAccountEmail(Number(lastInsertRowid), 'verify');
    return res.status(201).json({
      verificationRequired: true,
      message: 'Enviámos um link para confirmares o teu e-mail.'
    });
  }
  await createSession(res, lastInsertRowid);
  const user = await db.prepare('SELECT * FROM users WHERE id = ?').get(lastInsertRowid);
